"use client";

import { useEffect, useMemo, useRef, useState } from "react";

import { ProvenanceBadge } from "@/components/common/badges";
import { cn } from "@/lib/utils";

/*
 * Measure, detrend, fold, classify: the same synthetic star's points move between the four stages, so
 * you can watch the transit emerge. Generated by code (seeded), labelled as an illustration.
 */

const STEPS = [
  ["Measure", "Record the star's brightness over time: a light curve. Slow drifts and noise hide the dips."],
  ["Detrend", "Divide out slow changes from the star and the instrument, keeping short dips."],
  ["Fold", "Stack every orbit on top of the others using the signal's period. Repeating dips line up."],
  ["Classify", "Bin the folded curve into the network's views and judge the shape: a U-shaped transit, or an impostor."],
] as const;

const N = 900, DAYS = 90, PERIOD = 6.3, T0 = 2.1, DUR = 0.28, DEPTH = 0.006;

function rng(seed: number) {
  return () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296);
}

/** Point positions for each stage, normalised to 0..1 in both axes. */
function useStages() {
  return useMemo(() => {
    const r = rng(7);
    const gauss = () => Math.sqrt(-2 * Math.log(r() + 1e-9)) * Math.cos(2 * Math.PI * r());
    // uneven sampling, like a real cadence against a real period: evenly spaced times would fold into stripes
    const t = Array.from({ length: N }, () => r() * DAYS).sort((a, b) => a - b);
    const trend = t.map((x) => 1 + 0.012 * Math.sin(x / 9) + 0.006 * Math.sin(x / 2.7 + 1) + 0.00012 * x);
    const phase = t.map((x) => ((((x - T0) / PERIOD) % 1) + 1.5) % 1 - 0.5);      // -0.5..0.5, transit at 0
    const dip = phase.map((p) => {
      const h = Math.abs(p * PERIOD) / (DUR / 2);
      return h >= 1 ? 0 : DEPTH * (1 - Math.pow(h, 6));
    });
    const noise = t.map(() => gauss() * 0.0011);
    const raw = t.map((_, i) => trend[i] * (1 - dip[i]) + noise[i]);
    const flat = raw.map((v, i) => v / trend[i]);
    const norm = (vals: number[], lo: number, hi: number) => vals.map((v) => 1 - (v - lo) / (hi - lo));
    const raw01 = norm(raw, Math.min(...raw), Math.max(...raw));
    const flat01 = norm(flat, 1 - DEPTH * 1.6, 1 + 0.004);
    const x01 = t.map((x) => x / DAYS);
    const zoom = 0.12;                                                              // folded view: +-12% of phase
    const fx = phase.map((p) => Math.min(1, Math.max(0, 0.5 + p / (2 * zoom))));
    // classify: 64-bin local view
    const BINS = 64, sums = new Array(BINS).fill(0), counts = new Array(BINS).fill(0);
    phase.forEach((p, i) => {
      if (Math.abs(p) >= zoom) return;
      const b = Math.min(BINS - 1, Math.floor((p / (2 * zoom) + 0.5) * BINS));
      sums[b] += flat[i]; counts[b]++;
    });
    const binned = sums.map((s, b) => (counts[b] ? s / counts[b] : 1));
    const bx = phase.map((p) => Math.min(1, Math.max(0, 0.5 + p / (2 * zoom))));
    const by = phase.map((p) => {
      const b = Math.min(BINS - 1, Math.max(0, Math.floor((p / (2 * zoom) + 0.5) * BINS)));
      return 1 - (binned[b] - (1 - DEPTH * 1.6)) / (DEPTH * 1.6 + 0.004);
    });
    const inView = phase.map((p) => Math.abs(p) < zoom);
    return [
      { x: x01, y: raw01, show: t.map(() => true) },
      { x: x01, y: flat01, show: t.map(() => true) },
      { x: fx, y: flat01, show: inView },
      { x: bx, y: by, show: inView },
    ];
  }, []);
}

export function PipelineStages() {
  const stages = useStages();
  const [step, setStep] = useState(0);
  const canvas = useRef<HTMLCanvasElement>(null);
  const shown = useRef(0);            // the animated stage position, 0..3 (fractional while moving)

  useEffect(() => {
    const c = canvas.current, ctx = c?.getContext("2d");
    if (!c || !ctx) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let raf = 0;
    const draw = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const w = c.clientWidth, h = c.clientHeight;
      if (c.width !== Math.round(w * dpr)) { c.width = Math.round(w * dpr); c.height = Math.round(h * dpr); }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      const s = shown.current, a = Math.floor(s), b = Math.min(3, a + 1), k = s - a;
      const e = k * k * (3 - 2 * k);
      const A = stages[a], B = stages[b];
      const pad = 16;
      for (let i = 0; i < N; i++) {
        const vis = (A.show[i] ? 1 - e : 0) + (B.show[i] ? e : 0);
        if (vis < 0.02) continue;
        const x = pad + (A.x[i] + (B.x[i] - A.x[i]) * e) * (w - 2 * pad);
        const y = pad + (A.y[i] + (B.y[i] - A.y[i]) * e) * (h - 2 * pad);
        ctx.globalAlpha = vis * (s > 2.5 ? 0.9 : 0.55);
        ctx.fillStyle = s > 2.5 ? "#f3b45a" : "#dfe4ec";
        ctx.fillRect(x - 1, y - 1, s > 2.5 ? 2.4 : 1.8, s > 2.5 ? 2.4 : 1.8);
      }
      ctx.globalAlpha = 1;
    };
    const tick = () => {
      const d = step - shown.current;
      shown.current = reduce || Math.abs(d) < 0.002 ? step : shown.current + d * 0.08;
      draw();
      if (shown.current !== step) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    const ro = new ResizeObserver(draw);
    ro.observe(c);
    return () => { cancelAnimationFrame(raf); ro.disconnect(); };
  }, [step, stages]);

  const labels = ["brightness over 90 days", "after detrending", "folded on the 6.3-day period", "binned local view: the network's input"];

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_1.5fr]">
      <ol className="flex flex-col gap-2">
        {STEPS.map(([title, text], i) => (
          <li key={title}>
            <button type="button" onClick={() => setStep(i)} aria-pressed={step === i}
                    className={cn("glass w-full rounded-2xl px-4 py-3 text-left transition-colors",
                                  step === i ? "ring-1 ring-white/40" : "opacity-70 hover:opacity-100")}>
              <span className="data text-xs text-star">{String(i + 1).padStart(2, "0")}</span>
              <span className="ml-2 font-medium">{title}</span>
              <span className="mt-1 block text-sm leading-relaxed text-muted-foreground">{text}</span>
            </button>
          </li>
        ))}
      </ol>
      <figure className="glass flex flex-col rounded-2xl p-3 sm:p-4">
        <div className="flex items-center justify-between gap-3 px-1">
          <p className="eyebrow">{labels[step]}</p>
          <div className="flex gap-1">
            <button type="button" className="min-h-11 min-w-11 rounded-full text-muted-foreground hover:text-foreground disabled:opacity-40"
                    onClick={() => setStep((s) => Math.max(0, s - 1))} disabled={step === 0} aria-label="Previous stage">←</button>
            <button type="button" className="min-h-11 min-w-11 rounded-full text-muted-foreground hover:text-foreground disabled:opacity-40"
                    onClick={() => setStep((s) => Math.min(3, s + 1))} disabled={step === 3} aria-label="Next stage">→</button>
          </div>
        </div>
        <canvas ref={canvas} role="img" className="mt-2 h-64 w-full sm:h-80"
                aria-label={`Synthetic light curve, ${labels[step]}. ${step >= 2 ? "The repeating transit lines up into one clear dip." : "The transits are hidden among drifts and noise."}`} />
        <figcaption className="mt-2 flex flex-wrap items-center justify-between gap-2 px-1 text-xs text-muted-foreground">
          <span>Illustration: one synthetic star, {N} measurements, a 0.6% transit every {PERIOD} days.</span>
          <ProvenanceBadge kind="synthetic" />
        </figcaption>
      </figure>
    </div>
  );
}
